import {scriptTokens} from './notation.js';
import {fmt,nearOne} from './core.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export function niceStep(span,target=6){const raw=span/target,p=10**Math.floor(Math.log10(raw)),q=raw/p;return (q<=1?1:q<=2?2:q<=5?5:10)*p;}
export function validStep(v){if(!(v>0)||!Number.isFinite(v))return false;const mantissa=v/10**Math.floor(Math.log10(v));return [1,2,5].some(x=>Math.abs(mantissa-x)<1e-9);}
function autoAxis(v){let lo=Math.min(...v),hi=Math.max(...v);if(lo===hi){let pad=Math.abs(lo)*.1||1;lo-=pad;hi+=pad;}let pad=(hi-lo)*.06,step=niceStep(hi-lo+2*pad);if(lo>=0&&lo<(hi-lo)*.3)lo=0;else lo-=pad;hi+=pad;return {min:Math.floor(lo/step)*step,max:Math.ceil(hi/step)*step,step};}
export function axesFor(chart,overrides={}){const all=chart.series.flatMap(s=>[...(s.points??[]),...(s.line??[])]).concat((chart.special??[]).map(p=>[p.x,p.y]));if(!all.length)throw Error('图没有数据。');const axes={x:autoAxis(all.map(r=>r[0])),y:autoAxis(all.map(r=>r[1]))};for(const dim of ['x','y'])for(const k of ['min','max','step']){let v=overrides[dim+k];if(v!==''&&v!==null&&v!==undefined){v=Number(v);if(!Number.isFinite(v))throw Error('坐标设置须为有限数。');axes[dim][k]=v;}}for(const [dim,i] of [['x',0],['y',1]]){let a=axes[dim];if(a.min>=a.max)throw Error('坐标最大值须大于最小值。');if(!validStep(a.step))throw Error('主刻度须为1、2、5乘以10的整数次幂。');if((a.max-a.min)/a.step>25||(a.max-a.min)/a.step<2)throw Error('主刻度数量请保持2–25个，避免过密或过疏。');if(all.some(r=>r[i]<a.min-1e-10||r[i]>a.max+1e-10))throw Error('坐标范围裁掉了数据或曲线，请扩大范围。');}return axes;}
function minor(a){const mantissa=a.step/10**Math.floor(Math.log10(a.step));return a.step/(Math.abs(mantissa-2)<1e-8?10:5);}
const tick=v=>v===0?'0':Math.abs(v)>=1e5||Math.abs(v)<1e-3?Number(v.toPrecision(3)).toExponential().replace('e+','e'):String(Number(v.toPrecision(10)));
const svgNotation=(text,italic=false,size=19)=>{let offset=0;const runs=scriptTokens(text).map(t=>{const next=t.kind==='sup'?-size*.42:t.kind==='sub'?size*.24:0,dy=next-offset;offset=next;return `<tspan font-style="${italic?'italic':'normal'}" font-size="${t.kind==='normal'?size:size*.72}" dy="${dy}">${esc(t.text)}</tspan>`;}).join('');return runs+(offset?`<tspan dy="${-offset}" font-size="${size}"> </tspan>`:'');};
const label=(s,x,y,rot='')=>{const spaced=s.lastIndexOf(' / '),at=spaced>=0?spaced+1:s.indexOf('/'),v=at<0?s:s.slice(0,at),u=at<0?'':s.slice(at);return `<text x="${x}" y="${y}" text-anchor="middle" font-family="Times New Roman, Noto Sans SC, serif" ${rot?`transform="${rot}"`:''}>${svgNotation(v.trim(),true)}${u?svgNotation(' '+u,false):''}</text>`;};
export function specialPoints(chart,axis){if(!chart.fit)return [];const xs=chart.series.flatMap(s=>(s.points??[]).map(r=>r[0])),lo=Math.min(...xs),hi=Math.max(...xs),step=minor(axis.x),span=hi-lo;if(span<=step*3)return [];function point(start,dir){let v=dir>0?Math.ceil(start/step)*step:Math.floor(start/step)*step;for(let j=0;j<100;j++,v+=dir*step){if(v<lo||v>hi)return null;if(!xs.some(x=>Math.abs(v-x)<step*1e-7))return v;}return null;}const x1=point(lo+.03*span,1),x2=point(hi-.03*span,-1);return x1===null||x2===null||x2-x1<span*.5?[]:[{x:x1,y:chart.fit.k*x1+chart.fit.b,label:'P'},{x:x2,y:chart.fit.k*x2+chart.fit.b,label:'Q'}];}
export function svgChart(chart,meta={},options={}){const axis=axesFor(chart,options.axes),W=900,H=720,L=102,R=35,T=112,B=193,pw=W-L-R,ph=H-T-B;const X=x=>L+(x-axis.x.min)/(axis.x.max-axis.x.min)*pw,Y=y=>T+ph-(y-axis.y.min)/(axis.y.max-axis.y.min)*ph;let s=`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(chart.title)}"><rect width="900" height="720" fill="white"/><g fill="#111" font-family="Noto Sans SC, PingFang SC, Microsoft YaHei, sans-serif"><text x="450" y="35" font-size="24" text-anchor="middle">${esc(meta.experiment??'基础物理实验')}</text><text x="450" y="66" font-size="21" text-anchor="middle">${svgNotation(chart.title,false,21)}</text><text x="102" y="92" font-size="14">实验者：${esc(meta.author||'________')}</text><text x="620" y="92" font-size="14">实验日期：${esc(meta.date||'________')}</text>`;
 for(const [dim,a] of Object.entries(axis)){const st=minor(a),n=Math.floor((a.max-a.min)/st+1e-9);for(let i=0;i<=n;i++){let v=a.min+i*st,major=Math.abs(v/a.step-Math.round(v/a.step))<1e-7,color=major?'#c3c9cf':'#e7ebef';if(dim==='x')s+=`<line x1="${X(v)}" y1="${T}" x2="${X(v)}" y2="${T+ph}" stroke="${color}" stroke-width="${major?1:.6}"/>`;else s+=`<line x1="${L}" y1="${Y(v)}" x2="${L+pw}" y2="${Y(v)}" stroke="${color}" stroke-width="${major?1:.6}"/>`;}
 const first=Math.ceil(a.min/a.step)*a.step;for(let v=first;v<=a.max+1e-9*a.step;v+=a.step){if(dim==='x')s+=`<line x1="${X(v)}" y1="${T+ph}" x2="${X(v)}" y2="${T+ph+6}" stroke="#111"/><text x="${X(v)}" y="${T+ph+26}" font-size="15" text-anchor="middle">${esc(tick(v))}</text>`;else s+=`<line x1="${L-6}" y1="${Y(v)}" x2="${L}" y2="${Y(v)}" stroke="#111"/><text x="${L-12}" y="${Y(v)+5}" font-size="15" text-anchor="end">${esc(tick(v))}</text>`;}}
 s+=`<rect x="${L}" y="${T}" width="${pw}" height="${ph}" fill="none" stroke="#111" stroke-width="1.4"/>${label(chart.xlabel,L+pw/2,T+ph+58)}${label(chart.ylabel,28,T+ph/2,`rotate(-90 28 ${T+ph/2})`)}`;
 let pointIdx=0;const colors=['#141414','#175f89','#8b493a','#395f46','#663f7c','#767024'];function marker(x,y,i,size=5){const c=colors[i%colors.length];if(i%4===0)return `<path d="M${x-size} ${y}h${size*2}M${x} ${y-size}v${size*2}" fill="none" stroke="${c}" stroke-width="1.7"/>`;if(i%4===1)return `<circle cx="${x}" cy="${y}" r="${size}" fill="white" stroke="${c}" stroke-width="1.7"/>`;if(i%4===2)return `<path d="M${x-size} ${y-size}l${size*2} ${size*2}M${x-size} ${y+size}l${size*2} ${-size*2}" fill="none" stroke="${c}" stroke-width="1.7"/>`;return `<rect x="${x-size}" y="${y-size}" width="${size*2}" height="${size*2}" fill="white" stroke="${c}" stroke-width="1.7"/>`;}
 const legends=[];chart.series.forEach((series,i)=>{if(series.line){const path=series.line.map((r,j)=>`${j===0?'M':'L'}${X(r[0]).toFixed(3)} ${Y(r[1]).toFixed(3)}`).join('');const c=colors[i%colors.length];s+=`<path d="${path}" fill="none" stroke="${c}" stroke-width="1.9" ${series.dash?'stroke-dasharray="8 5"':''}/>`;legends.push({name:series.name,color:c,line:true,dash:series.dash});}if(series.points){const n=pointIdx++;series.points.forEach(r=>s+=marker(X(r[0]),Y(r[1]),n));legends.push({name:series.name,point:n});}});
 const specials=[...(chart.special??[]),...(options.special?specialPoints(chart,axis):[])];for(const p of specials){let x=X(p.x),y=Y(p.y);s+=`<path d="M${x} ${y-7}l-7 13h14z" fill="white" stroke="#111" stroke-width="1.6"/>`;const right=x<L+pw*.65,text=`${p.label}=(${fmt(p.x,5)}, ${fmt(p.y,5)})`;s+=`<text x="${x+(right?10:-10)}" y="${y-13}" text-anchor="${right?'start':'end'}" font-size="14" fill="#111">${esc(text)}</text>`;}
 legends.forEach((l,i)=>{let x=L+(i%3)*260,y=T+ph+92+Math.floor(i/3)*24;if(l.line)s+=`<line x1="${x}" x2="${x+26}" y1="${y-4}" y2="${y-4}" stroke="${l.color}" stroke-width="1.9" ${l.dash?'stroke-dasharray="7 4"':''}/>`;else s+=marker(x+13,y-4,l.point,4);s+=`<text x="${x+34}" y="${y}" font-size="13">${esc(l.name)}</text>`;});
 const info=chart.fit?`Y=${fmt(chart.fit.k,5)}X ${chart.fit.b<0?'−':'+'} ${fmt(Math.abs(chart.fit.b),5)}    R²=${nearOne(chart.fit.r2)}`:specials.length?'三角形表示计算取点；原始数据点不标数值。':'曲线名称已区分测量、模型和插值。';s+=`<text x="${L}" y="699" font-size="14">${esc(info)}</text></g></svg>`;return {svg:s,axis,specials};}
export async function pngFromSvg(svg,width=2100){const img=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{await new Promise((res,rej)=>{img.onload=res;img.onerror=()=>rej(Error('图片生成失败。'));img.src=url;});const canvas=document.createElement('canvas');canvas.width=width;canvas.height=Math.round(width*720/900);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);return new Uint8Array(await (await new Promise(res=>canvas.toBlob(res,'image/png'))).arrayBuffer());}finally{URL.revokeObjectURL(url);}}
